$ErrorActionPreference='Stop'
$root=Split-Path -Parent $MyInvocation.MyCommand.Path;$art=Join-Path $root 'artifacts';$pub=Join-Path $art 'publish';$install=Join-Path $env:LOCALAPPDATA 'BlackLabel\Ace\AcceptanceInstall';foreach($p in @($art,$install)){if(Test-Path $p){Remove-Item $p -Recurse -Force}}
dotnet publish (Join-Path $root 'Ace.csproj') -c Release -r win-x64 --self-contained true -p:PublishSingleFile=true -o $pub;New-Item -ItemType Directory -Force $install|Out-Null;Copy-Item (Join-Path $pub '*') $install -Recurse -Force;$exe=Join-Path $install 'Ace.exe'
$self=& $exe --self-test|ConvertFrom-Json;if(-not $self.passed-or-not $self.shipsEmpty-or-not $self.signalsOnly-or-not $self.reviewGate-or-not $self.privateBoundary-or $self.requiredResiduals-ne 0-or $self.featureCount-ne 12-or $self.build-ne 87){throw 'Ace self-test failed'}
$smoke=Join-Path $art 'smoke.txt';$p=Start-Process $exe -ArgumentList '--smoke' -RedirectStandardOutput $smoke -PassThru -Wait;if($p.ExitCode-ne 0-or(Get-Content $smoke -Raw)-notmatch 'loaded=true'){throw 'Ace launch failed'}
$forbidden=Get-ChildItem $pub -Recurse -Force|Where-Object{$_.Name-in @('auth.json','transcript.md','memory.md','credentials.json')-or $_.Extension-in @('.pem','.key','.token')};if($forbidden){throw "ships-empty violation: $($forbidden[0].FullName)"};$zip=Join-Path $art 'Ace-win-x64.zip';Compress-Archive (Join-Path $pub '*') $zip;Remove-Item $install -Recurse -Force
[ordered]@{compiled=$true;installed=$true;launched=$true;selfTestPassed=$self.passed;shipsEmpty=$self.shipsEmpty;reviewGate=$self.reviewGate;privateBoundary=$self.privateBoundary;signalsOnly=$self.signalsOnly;build=$self.build;featureCount=$self.featureCount;requiredResiduals=$self.requiredResiduals;package=[ordered]@{bytes=(Get-Item $zip).Length;sha256=(Get-FileHash $zip -Algorithm SHA256).Hash.ToLowerInvariant()};uninstalled=(-not(Test-Path $install))}|ConvertTo-Json -Depth 8|Set-Content (Join-Path $art 'windows-acceptance.json') -Encoding utf8
